func configureFormTheme() huh.Theme {
	return huh.ThemeFunc(func(isDark bool) *huh.Styles {
		theme := uiform.Theme().Theme(isDark)
		// The standard huh theme draws a thick vertical rail around whichever
		// field is focused. Configure is one continuous checklist, matching the
		// prototype, so focus is expressed by its selectors rather than a panel.
		theme.Focused.Base = lipgloss.NewStyle()
		theme.Blurred.Base = lipgloss.NewStyle()
		theme.Focused.SelectSelector = theme.Focused.SelectSelector.SetString("● ")
		theme.Blurred.SelectSelector = theme.Blurred.SelectSelector.SetString("● ")
		theme.Focused.MultiSelectSelector = theme.Focused.MultiSelectSelector.SetString("› ")
		theme.Blurred.MultiSelectSelector = theme.Blurred.MultiSelectSelector.SetString("  ")
		theme.Focused.SelectedPrefix = theme.Focused.SelectedPrefix.SetString("◼ ")
		theme.Blurred.SelectedPrefix = theme.Blurred.SelectedPrefix.SetString("◼ ")
		theme.Focused.UnselectedPrefix = theme.Focused.UnselectedPrefix.SetString("◻ ")
		theme.Blurred.UnselectedPrefix = theme.Blurred.UnselectedPrefix.SetString("◻ ")
		return theme
	})
}

