func (field *configureAgentField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
		switch {
		case configureUpKey(keyMsg.String()):
			if field.cursor == 0 {
				return field, huh.PrevField
			}
			field.cursor--
		case configureDownKey(keyMsg.String()):
			field.cursor++
			if field.cursor >= field.count {
				field.cursor = 0
			}
		}
	}
	model, cmd := field.MultiSelect.Update(msg)
	if updated, ok := model.(*huh.MultiSelect[string]); ok {
		field.MultiSelect = updated
	}
	return field, cmd
}

func configureNextKey(key string) bool {
	return key == "enter" || key == "tab"
}

func configureUpKey(key string) bool {
	switch key {
	case "up", "k", "ctrl+k", "ctrl+p":
		return true
	default:
		return false
	}
}

func configureDownKey(key string) bool {
	switch key {
	case "down", "j", "ctrl+j", "ctrl+n":
		return true
	default:
		return false
	}
}

func firstSelectedAgentOption(options []huh.Option[string], selected map[types.AgentName]struct{}) int {
	for i, option := range options {
		if _, ok := selected[types.AgentName(option.Value)]; ok {
			return i
		}
	}
	return 0
}

