func configureSaveOptions(branch string, protected bool, selected string) []huh.Option[string] {
	direct := "Push to " + branch
	if protected {
		direct += " — protected branch"
	}
	return []huh.Option[string]{
		huh.NewOption(configureRadioLabel(direct, selected == configureSaveDirect), configureSaveDirect),
