	description := "Arrow keys to move · shift+tab to go back · enter to save"
	if protected {
		disabled := lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Render("  ○ Push to " + branch + " — protected branch")
		description += "\n" + disabled
	}
	return description
}

